import glob
import hashlib
import os
import re
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any, Optional

import yaml

from jinja2 import Environment, FileSystemLoader, StrictUndefined, Template
from jinja2.ext import Extension

from .context import Context, NamespaceCtx
from .context.api import indent
from .schema import Root as RootSchema

TOKEN: str = "".join(["<<", "SignedSource", "::", "*O*zOeWoEQle#+L!plEphiEmie@IsG", ">>"])


class SignedSourceC(Extension):
    HEADER: str = "".join(
        [
            "// DO NOT EDIT: this file was generated by 'just codegen'\n",
            "// ",
            "@",
            "g",
            "enerated ",
            TOKEN,
            "\n",
        ]
    )

    def preprocess(self, source: str, name: Optional[str], filename: Optional[str] = None) -> str:
        return self.HEADER + source


class SignedSourceErl(Extension):
    PREFIX: str = "".join(["%" * 3, " %"])
    HEADER: str = "".join(
        [
            PREFIX,
            " DO NOT EDIT: this file was generated by 'just codegen'\n",
            PREFIX,
            " @",
            "g",
            "enerated ",
            TOKEN,
            "\n",
        ]
    )

    def preprocess(self, source: str, name: Optional[str], filename: Optional[str] = None) -> str:
        return self.HEADER + source


class SignedSourceMarkdown(Extension):
    HEADER = "<!--\nDO NOT EDIT: this file was generated by 'just codegen'\n@generated " + TOKEN + "\n-->\n"

    def preprocess(self, source: str, name: Optional[str], filename: Optional[str] = None) -> str:
        return self.HEADER + source


def sign_source(source: bytes) -> bytes:
    token = TOKEN.encode("utf-8")
    needle = re.compile(rb"(?:SignedSource<<[a-f0-9]{32}>>)|" + re.escape(token))
    if needle.search(source) is None:
        return source
    unsigned = needle.sub(token, source)
    signature = f"SignedSource<<{hashlib.md5(unsigned).hexdigest()}>>".encode("utf-8")
    return needle.sub(signature, source)


def load_config(config_file: str) -> RootSchema:
    """Load `config.yaml` and merge the namespace definitions beside it."""
    with open(config_file, "r", encoding="utf-8") as f:
        data: Any = yaml.safe_load(f) or {}
    namespaces = data.setdefault("namespaces", {})
    for path in sorted(Path(config_file).parent.joinpath("namespaces").glob("*.yaml")):
        with open(path, "r", encoding="utf-8") as f:
            for name, namespace in (yaml.safe_load(f) or {}).items():
                if name in namespaces:
                    raise ValueError(f"{path.name}: namespace {name} is already defined")
                namespaces[name] = namespace
    return RootSchema.model_validate(data)


@dataclass
class Stage:
    codegen: "CodeGenerator" = field(repr=False)
    templates_path: str
    targets: list["StageTarget"] = field(init=False)
    c_env: Environment = field(init=False)
    erl_env: Environment = field(init=False)
    markdown_env: Environment = field(init=False)

    def __post_init__(self) -> None:
        self.targets = []
        for template_name in sorted(glob.iglob("**", root_dir=self.templates_path, recursive=True)):
            if os.path.isfile(os.path.join(self.templates_path, template_name)):
                output_name, template_ext = os.path.splitext(template_name)
                if template_ext != ".j2":
                    continue
                if "[namespace]" in output_name or "[module]" in output_name:
                    for namespace in self.codegen.ctx.namespaces:
                        self.targets.append(
                            StageTarget(
                                stage=self,
                                template_name=template_name,
                                output_name=output_name.replace("[namespace]", namespace.name).replace(
                                    "[module]", namespace.module
                                ),
                                namespace=namespace,
                            )
                        )
                else:
                    self.targets.append(
                        StageTarget(
                            stage=self,
                            template_name=template_name,
                            output_name=output_name,
                        )
                    )
        self.c_env = Environment(
            loader=FileSystemLoader(self.templates_path, encoding="utf-8"),
            comment_start_string="/* clang-format ",
            comment_end_string=" */ //-",
            trim_blocks=True,
            lstrip_blocks=True,
            keep_trailing_newline=True,
            undefined=StrictUndefined,
        )
        self.c_env.add_extension("jinja2.ext.debug")
        self.c_env.add_extension(SignedSourceC)
        self.c_env.filters["indent_lines"] = indent
        self.erl_env = Environment(
            loader=FileSystemLoader(self.templates_path, encoding="utf-8"),
            # block_start_string="<<{%",
            # block_end_string="%}>>",
            # variable_start_string="<<{{",
            # variable_end_string="}}>>",
            # comment_start_string="<<{#",
            # comment_end_string="#}>>",
            block_start_string="~J{",
            block_end_string="}.",
            variable_start_string="~J<",
            variable_end_string=">.",
            comment_start_string="~J#",
            comment_end_string="#.",
            trim_blocks=True,
            lstrip_blocks=True,
            keep_trailing_newline=True,
            undefined=StrictUndefined,
        )
        self.erl_env.add_extension("jinja2.ext.debug")
        self.erl_env.add_extension(SignedSourceErl)
        self.markdown_env = Environment(
            loader=FileSystemLoader(self.templates_path, encoding="utf-8"),
            block_start_string="~J{",
            block_end_string="}.",
            variable_start_string="~J<",
            variable_end_string=">.",
            comment_start_string="~J#",
            comment_end_string="#.",
            trim_blocks=True,
            lstrip_blocks=True,
            keep_trailing_newline=True,
            undefined=StrictUndefined,
            extensions=[SignedSourceMarkdown],
        )

    def clean(self) -> None:
        for target in self.targets:
            target.clean()
        return

    def render(self) -> None:
        for target in self.targets:
            target.render()
        return

    def sign(self) -> None:
        for target in self.targets:
            target.sign()
        return


@dataclass
class StageTarget:
    stage: "Stage" = field(repr=False)
    template_name: str
    output_name: str
    namespace: Optional[NamespaceCtx] = None
    output_path: str = field(init=False)
    output_file: str = field(init=False)
    is_erl: bool = field(init=False)

    def __post_init__(self) -> None:
        _, output_ext = os.path.splitext(self.output_name)
        if output_ext in (".erl", ".hrl", ".xrl", ".yrl"):
            self.is_erl = True
        else:
            self.is_erl = False
        self.output_file = os.path.join(self.codegen.output_path, self.output_name)
        self.output_path = os.path.dirname(self.output_file)
        return

    @property
    def codegen(self) -> "CodeGenerator":
        return self.stage.codegen

    @property
    def env(self) -> Environment:
        if self.output_name.endswith(".md"):
            return self.stage.markdown_env
        elif self.is_erl:
            return self.stage.erl_env
        else:
            return self.stage.c_env

    @property
    def label(self) -> str:
        if self.output_name.endswith(".md"):
            return "M"
        elif self.is_erl:
            return "E"
        else:
            return "C"

    def clean(self) -> None:
        if os.path.isfile(self.output_file):
            os.remove(self.output_file)
        return

    def render(self) -> None:
        os.makedirs(self.output_path, exist_ok=True)
        template: Template = self.env.get_template(self.template_name)
        print(f"[{self.label}] {self.output_name}")
        template.stream(ctx=self.codegen.ctx, namespace=self.namespace).dump(self.output_file, encoding="utf-8")
        # self.sign()
        return

    def sign(self) -> None:
        output = Path(self.output_file)
        output.write_bytes(sign_source(output.read_bytes()))


@dataclass
class CodeGenerator:
    config_file: str
    output_path: str
    templates0_path: str
    templates1_path: str
    templates2_path: Optional[str] = None
    ctx: Context = field(init=False)
    stage0: Stage = field(init=False)
    stage1: Stage = field(init=False)
    stage2: Optional[Stage] = field(init=False)

    def __post_init__(self) -> None:
        self.ctx = Context(_output_path=self.output_path, schema=load_config(self.config_file))
        self.stage0 = Stage(codegen=self, templates_path=self.templates0_path)
        self.stage1 = Stage(codegen=self, templates_path=self.templates1_path)
        self.stage2 = Stage(codegen=self, templates_path=self.templates2_path) if self.templates2_path else None

    def render(self) -> None:
        self.ctx.reset_atoms()
        print("Stage0 Render")
        self.stage0.render()
        self._analyze_c_src_nif_atoms()
        print("Stage1 Render")
        self.stage1.render()

    def sign(self) -> None:
        print("Stage0 Sign")
        self.stage0.sign()
        print("Stage1 Sign")
        self.stage1.sign()
        if self.stage2 is not None:
            print("Stage2 Sign")
            self.stage2.sign()

    def render_docs(self, check: bool = False, library_path: Optional[str] = None) -> None:
        from .documentation import ErlangExamples

        if self.stage2 is None:
            raise ValueError("Documentation generation requires a templates2 directory")
        examples = ErlangExamples(Path(library_path) if library_path else Path(self.output_path) / "ebin")
        print("Stage2 Render")
        outputs = []
        for target in self.stage2.targets:
            examples.reset()
            template = target.env.get_template(target.template_name)
            rendered = template.render(ctx=self.ctx, erlang=examples.expression)
            rendered = examples.resolve(rendered)
            examples.verify(rendered, target.output_name)
            outputs.append((target, sign_source(rendered.encode("utf-8"))))
        # Validate every output before replacing any committed documentation.
        for target, source in outputs:
            output = Path(target.output_file)
            if check:
                if not output.is_file() or output.read_bytes() != source:
                    raise ValueError(f"{target.output_name} is out of date; run just codegen")
                print(f"[M] {target.output_name} is current")
            else:
                output.parent.mkdir(parents=True, exist_ok=True)
                output.write_bytes(source)
                print(f"[M] {target.output_name}")

    def _analyze_c_src_nif_atoms(self) -> None:
        root = Path(self.output_path, "c_src", "nif")
        generated_atoms = {Path(target.output_file).resolve() for target in self.stage1.targets}
        comments_and_literals = re.compile(r"""//[^\n]*|/\*.*?\*/|"(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])*' """, re.DOTALL | re.VERBOSE)
        for source in sorted(root.rglob("*")):
            if not source.is_file() or source.suffix not in (".c", ".h") or source.resolve() in generated_atoms:
                continue
            contents = comments_and_literals.sub(" ", source.read_text(encoding="utf-8"))
            contents = re.sub(r"(?m)^\s*#\s*define\s+ATOM\s*\([^)]*\)", "", contents)
            for name in re.findall(r"\bATOM\s*\(\s*([a-z][a-zA-Z0-9_]*)\s*\)", contents):
                self.ctx.nif.make_atom(name)
